export function ErrorStateCard({
  title = "Something went wrong",
  message,
  retryLabel = "Retry",
  onRetry,
}: ErrorStateCardProps) {
  return (
    <StateCard
      icon={Warning}
      iconColor="warning.main"
      title={title}
      message={message}
      action={
        onRetry ? (
          <Button variant="soft" onClick={onRetry}>
            {retryLabel}
          </Button>
        ) : undefined
      }
    />
  );
}
